WITH filtered AS (SELECT *, CONCAT(country, ' - ', device) AS country_device FROM sessions WHERE started_at >= TIMESTAMP '2023-08-18 10:00:00' AND country IS NOT NULL) SELECT *, LAST_VALUE(browser) IGNORE NULLS OVER (PARTITION BY browser ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_browser, FIRST_VALUE(country) IGNORE NULLS OVER w_hist AS first_known_country, ROW_NUMBER() OVER (PARTITION BY country ORDER BY started_at, id) AS row_seq, FIRST_VALUE(country) IGNORE NULLS OVER w_hist AS first_known_country_2 FROM filtered WINDOW w_hist AS (PARTITION BY customer_id ORDER BY started_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW);
